pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address _accessControl) public {
        vm.assume(_accessControl != address(0));
        c.initialize(_accessControl);

        // The UUPS proxy implementation check: after initialization, calling proxiableUUID() 
        // on the non-proxy (implementation) contract should revert because notDelegated check fails.
        // Reference P: reverts (UUPSUnauthorizedCallContext) after full UUPS init.
        // Mutant M: since __UUPSUpgradeable_init is skipped, _isInitializing() and _initialized state differ,
        // and the notDelegated check may also differ, causing a different revert or even return a value.
        bool ok;
        try c.proxiableUUID() returns (bytes32) {
            ok = true;
        } catch {
            ok = false;
        }

        // For the reference C, proxiableUUID() must always revert because `__self` check (address(this) != __self)
        // inside notDelegated, and we are on the implementation directly. The property: after initialize,
        // proxiableUUID() always reverts. The mutant may return a value (or revert differently) due to missing UUPS init.
        assertFalse(ok);
    }
}

