import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address admin, uint256 maxMult, uint256 minMult, uint256 rate) public {
        vm.assume(admin != address(0));
        vm.assume(admin != address(this));
        vm.assume(admin.code.length == 0);

        // Adversarial helper: minimal contract whose only role is to act as the accessControl
        // and return true when checkAccess is called. Without code, address(0) returns
        // false from staticcall, so the buggy version will deny access.
        AccessGranter granter = new AccessGranter();

        // Initialize with the granter as accessControl.
        // For the correct contract, this sets accessControl = granter.
        // For the buggy contract, initialize(address(0)) is called, ignoring _accessControl.
        vm.prank(admin);
        c.initialize(address(granter));

        // Attempt a checkAccess-gated call.
        // The correct contract asks granter.checkAccess(...) which returns true -> success.
        // The buggy contract asks address(0).checkAccess(...), which reverts or returns false.
        bool ok;
        vm.prank(admin);
        try c.setLimits(maxMult, minMult, rate) {
            ok = true;
        } catch {
            ok = false;
        }

        // The property: after initialization, a checkAccess-gated function must succeed
        // (i.e., not revert) when called with a legitimate accessControl.
        assertTrue(ok);
    }
}

// Minimal helper that implements the IAccessControl interface partially:
// - checkAccess always returns true.
// Other functions revert if called, but they are not needed in this scenario.
contract AccessGranter {
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }

    // Fallback to satisfy any unexpected calls or interface compliance.
    fallback() external payable {
        // Do nothing; accept calls gracefully to prevent revert from low-level call.
    }
}

