pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IAccessControl {
    function initialize(address _admin) external;
    function grantAccess(bytes4 _selector, address _contract, address _address) external;
    function revokeAccess(bytes4 _selector, address _contract, address _address) external;
    function checkAccess(bytes4 _selector, address _contract, address _caller) external view returns (bool hasAccess);
    function role(bytes4 _selector, address _contract) external pure returns (bytes32 roleId);
}

contract MockAccessControl is IAccessControl {
    mapping(bytes4 => mapping(address => mapping(address => bool))) private _access;
    address public admin;

    function initialize(address _admin) external {
        admin = _admin;
    }

    function grantAccess(bytes4 _selector, address _contract, address _address) external {
        _access[_selector][_contract][_address] = true;
    }

    function revokeAccess(bytes4 _selector, address _contract, address _address) external {
        _access[_selector][_contract][_address] = false;
    }

    function checkAccess(bytes4 _selector, address _contract, address _caller) external view returns (bool hasAccess) {
        return _access[_selector][_contract][_caller];
    }

    function role(bytes4 _selector, address _contract) external pure returns (bytes32 roleId) {
        return keccak256(abi.encodePacked(_selector, _contract));
    }
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address admin, address nonAdmin) public {
        vm.assume(admin != address(0) && nonAdmin != address(0));
        vm.assume(admin != nonAdmin);

        MockAccessControl ac = new MockAccessControl();

        // Step 1: nonAdmin initializes C
        vm.prank(nonAdmin);
        c.initialize(address(ac));

        // Step 2: admin initializes the access control contract
        ac.initialize(admin);

        // Step 3: admin attempts to reinitialize C with version 2
        // In reference, reinitializer succeeds (initial version is 1)
        // In mutant, reinitializer reverts because initial version was set to 2
        vm.prank(admin);
        (bool success, ) = address(c).call(
            abi.encodeWithSelector(
                bytes4(keccak256("reinitialize(uint64,address)")),
                uint64(2),
                address(ac)
            )
        );

        // Step 4: Read back the effect on accessControl
        // If reinitializer succeeded, accessControl should be admin.
        // If it reverted, accessControl remains nonAdmin.

        // Use a public getter: the stored access control address is exposed via checkAccess call.
        // But we need a public view function that reveals the stored accessControl address.
        // The contract has no direct public getter for accessStorage.accessControl.
        // However, we can call checkAccess through the access control contract itself.
        // The access control contract has a public admin variable.
        // The stored accessControl address in c is what it uses to call checkAccess.
        // So we can indirectly observe it by calling a function that uses checkAccess modifier.
        // The contract has setLimits and setSlopes that use checkAccess.
        // We can grant access to the admin on the mock, and then call setLimits from admin.
        // In reference: admin is the accessControl, so call from admin will succeed.
        // In mutant: nonAdmin is the accessControl, so call from admin will revert with AccessDenied.
        if (success) {
            // reinitialize succeeded, so accessControl should be admin
            ac.grantAccess(bytes4(keccak256("setLimits(uint256,uint256,uint256)")), address(c), admin);
        } else {
            // reinitialize reverted, so accessControl should still be nonAdmin
            ac.grantAccess(bytes4(keccak256("setLimits(uint256,uint256,uint256)")), address(c), nonAdmin);
        }

        bool callSucceeded;
        vm.prank(admin);
        try c.setLimits(1, 1, 1) {
            callSucceeded = true;
        } catch {
            callSucceeded = false;
        }

        // Property: If reinitialize succeeded, call to setLimits from admin should succeed.
        // If reinitialize reverted, call to setLimits from admin should fail.
        assertTrue(success == callSucceeded);
    }
}

