pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint256 kink,
        uint256 slope0,
        uint256 slope1,
        uint256 maxMultiplier,
        uint256 minMultiplier,
        uint256 rateParam
    ) public {
        // Admissible domain: kink in (0, 1e27), slopes and limits reasonable
        vm.assume(kink > 0 && kink < 1e27);
        vm.assume(slope0 >= 1 && slope0 <= 1000);
        vm.assume(slope1 >= 1 && slope1 <= 1000);
        vm.assume(maxMultiplier >= 1e27 && maxMultiplier <= 1e36);
        vm.assume(minMultiplier >= 1e18 && minMultiplier <= 1e27 && minMultiplier <= maxMultiplier);
        vm.assume(rateParam >= 1 && rateParam <= 1e18);

        // Deploy minimal adversarial helper simulating a vault
        VaultHelper helper = new VaultHelper();
        address vault = address(helper);
        address asset = makeAddr("asset");

        // Initialize c
        c.initialize(address(this));
        // Set slopes and limits
        C.SlopeData memory sd = C.SlopeData({kink: kink, slope0: slope0, slope1: slope1});
        c.setSlopes(asset, sd);
        c.setLimits(maxMultiplier, minMultiplier, rateParam);

        // Set up vault helper utilization state: initial index 1e27, low utilization 0
        helper.setUtilizationState(1e27, 0, true, 0);

        // First rate call at t=0: initial multiplier setting
        vm.warp(0);
        uint256 rate0 = c.rate(vault, asset);

        // Move time forward so next call triggers utilization calculation
        vm.warp(100);
        // Set utilization to high value (above kink) and index change
        // Use index = 1e27 + 1e18, so (index - lastIndex)/elapsed = 1e18/100 = 1e16
        helper.setUtilizationState(1e27 + 1e18, 1e27, true, 0);
        uint256 rate1 = c.rate(vault, asset);

        // Now call rate again in the same block (timestamp unchanged)
        // For correct contract: elapsed = 0 -> no multiplier change -> rate unchanged
        // For bug: elapsed = 1 -> multiplier change -> rate changes
        uint256 rate2 = c.rate(vault, asset);

        // The correct contract must return equal rates for the second and third calls
        // The buggy contract may return different rates
        assertTrue(rate1 == rate2);
    }
}

// Minimal adversarial helper simulating a vault with controllable utilization and index
contract VaultHelper {
    uint256 public currentUtilizationIndexVal;
    uint256 public utilizationVal;
    bool public pausedVal;

    function setUtilizationState(uint256 _index, uint256 _util, bool _paused, uint256 /*_totalSupply*/) external {
        currentUtilizationIndexVal = _index;
        utilizationVal = _util;
        pausedVal = _paused;
    }

    function currentUtilizationIndex(address /*_asset*/) external view returns (uint256) {
        return currentUtilizationIndexVal;
    }

    function utilization(address /*_asset*/) external view returns (uint256) {
        return utilizationVal;
    }

    function paused(address /*_asset*/) external view returns (bool) {
        return pausedVal;
    }
}

