contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize(address(0x123));
        vm.warp(10000);
    }

    function testFuzz_property(uint256 utilization, uint256 index, uint256 slope0, uint256 slope1, uint256 multiplier, uint256 lastUpdate) public {
        // Keep utilization and index reasonable to avoid overflow in computation
        vm.assume(utilization <= 1e27);
        vm.assume(index <= 1e27);
        vm.assume(index >= utilization);
        // lastUpdate must be in the past so elapsed > 0
        vm.assume(lastUpdate > 0 && lastUpdate < block.timestamp);
        // slopes and multiplier in reasonable ranges
        vm.assume(slope0 <= 1e27 && slope1 <= 1e27);
        vm.assume(multiplier > 0 && multiplier <= 1e27);

        // Deploy a mock vault that returns specified values
        MockVault vault = new MockVault(utilization, index);
        // Deploy a mock access control that always grants access
        MockAccessControl access = new MockAccessControl();
        // Re-initialize c with mock access control so setSlopes and setLimits can be called
        c = new C();
        c.initialize(address(access));
        vm.startPrank(address(0x1));
        // Set slopes for asset
        VaultAdapter.SlopeData memory slopes = VaultAdapter.SlopeData({ kink: 0.5e27, slope0: slope0, slope1: slope1 });
        c.setSlopes(address(0x1), slopes);
        // Set limits
        c.setLimits(1e27, 0, 1e18);
        // Set lastUpdate and index directly via storage manipulation (allowed setup)
        bytes32 slot = 0x2b1d5d801322d1007f654ac87d8072a5f5ca4203517edc869ef2aa54addad600;
        bytes32 utilizationSlot = keccak256(abi.encode(address(vault), uint256(uint160(0x1)), uint256(slot + 1)));
        // store multiplier
        vm.store(address(c), bytes32(uint256(keccak256(abi.encodePacked(uint256(uint160(address(vault))), bytes32(uint256(uint160(0x1)) + uint256(keccak256(abi.encodePacked(uint256(slot + 1))))))))), bytes32(multiplier));
        // store index
        vm.store(address(c), bytes32(uint256(keccak256(abi.encodePacked(uint256(uint160(address(vault))), bytes32(uint256(uint160(0x1)) + uint256(keccak256(abi.encodePacked(uint256(slot + 1))))) + 1)))), bytes32(index));
        // store lastUpdate
        vm.store(address(c), bytes32(uint256(keccak256(abi.encodePacked(uint256(uint160(address(vault))), bytes32(uint256(uint160(0x1)) + uint256(keccak256(abi.encodePacked(uint256(slot + 1))))) + 2)))), bytes32(lastUpdate));
        vm.stopPrank();

        vm.warp(block.timestamp + 1);
        // First call
        uint256 rate1 = c.rate(address(vault), address(0x1));
        // Second call within same block
        uint256 rate2 = c.rate(address(vault), address(0x1));

        assertTrue(rate1 == rate2);
    }
}

